function evidence = f90_xbatt04_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XBATT04_EXTRACT_CANDIDATE_EVIDENCE Public-contract candidate adapter.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot,sharedRoot]=localRoots("F90-XBATT-04");
addpath(sharedRoot,"-begin"); cleanup=onCleanup(@()rmpath(sharedRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xbatt04-evidence.v1", ...
    "task_id","F90-XBATT-04","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localInputs, ...
    "stop_time",@(~,~)str2double(string(official.simulation.stop_time)), ...
    "postprocess",@localPostprocess,"static_audit",@localAudit, ...
    "coverage_mode","event_terminated","evidence_sample_count",4000, ...
    "evidence_sample_s", ...
        str2double(string(official.simulation.stop_time))/3999);
evidence=simuverity_run_candidate_evidence(candidatePath,outDir,spec);
end
function rows=localOutputs
rows=localRows(["electrical_state","electrochemical_state","ageing_state"], ...
    [4 4 5]);
rows(1).event_columns=4;
end
function inputs=localInputs(s,~), inputs=rmfield(s,"id"); end
function row=localPostprocess(row,outputs,scenario,~)
completed=max(double(outputs.electrical_state(:,4)));
requested=double(scenario.number_of_cycles);
row.outputs=outputs;
row.metrics=struct("completed_cycle_count",completed, ...
    "requested_cycle_count",requested, ...
    "requested_cycle_count_reached",completed>=requested);
row.valid=row.output_contract.all_required_pass&&completed>=requested;
end
function audit=localAudit(model,spec)
structure=simuverity_candidate_structure( ...
    model,string({spec.output_contract.name})');
semantic=structure.semantic_types;
electrochemical=nnz(contains(semantic, ...
    ["battery","electrochemical","electrode","cell"]));
thermal=nnz(contains(semantic,["thermal","temperature","convective"]));
dynamic=structure.dynamic_block_count;
audit=struct("electrochemical_mechanism_count",electrochemical, ...
    "thermal_mechanism_count",thermal, ...
    "dynamic_state_block_count",dynamic, ...
    "connected_public_output_count",structure.connected_output_count, ...
    "nontrivial_public_output_source_count", ...
        structure.nontrivial_output_source_count, ...
    "core_path_qualified", ...
        structure.connected_output_count==numel(spec.output_contract) && ...
        structure.nontrivial_output_source_count==numel(spec.output_contract) && ...
        dynamic>=1);
end
function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear","event_columns",[]),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
        rows(k).width=widths(k);end
end
function [taskRoot,sharedRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end
